import AppKit
import SwiftUI

struct ContentView: View {
    @EnvironmentObject private var taskStore: TaskStore
    @EnvironmentObject private var controller: AppController
    @State private var sidebarSearchText = ""
    @State private var didRunInitialPageSetup = false

    var body: some View {
        VStack(spacing: 0) {
            Group {
                if controller.mainPage == .history {
                    historyView
                } else {
                    SettingsView(showBackButton: true) {
                        controller.showHistoryPage()
                    }
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            statusBar
        }
        .preferredColorScheme(.dark)
        .swissCanvas()
        .onAppear {
            if controller.selectedTaskID == nil {
                controller.selectedTaskID = taskStore.tasks.first?.id
            }
            if !didRunInitialPageSetup {
                didRunInitialPageSetup = true
                if controller.mainPage != .history {
                    controller.showHistoryPage()
                }
            }
        }
    }

    // MARK: - History layout (fully custom — no NavigationSplitView / List)

    private var historyView: some View {
        HStack(spacing: 0) {
            // ── Sidebar ───────────────────────────────────────────────────
            CocoSidebar(
                tasks: filteredTasks,
                searchText: $sidebarSearchText,
                selectedID: $controller.selectedTaskID,
                onSettings: { controller.showSettingsPage() }
            )
            .frame(width: 216)
            .accessibilityIdentifier("taskList")

            Divider()

            // ── Main content ──────────────────────────────────────────────
            Group {
                if let selectedID = controller.selectedTaskID {
                    TaskDetailView(taskID: selectedID)
                } else {
                    ContentUnavailableView(
                        "No Task Selected",
                        systemImage: "waveform",
                        description: Text("Press the global hotkey to create a transcription task.")
                    )
                    .swissCanvas()
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)

            // ── Right panel ───────────────────────────────────────────────
            if let selectedID = controller.selectedTaskID,
               let task = taskStore.task(id: selectedID) {
                Divider()
                CocoMetaPanel(task: task)
                    .frame(width: 200)
            }
        }
        .onChange(of: sidebarSearchText) { _, _ in
            keepValidSelectionDeferred()
        }
        .onChange(of: taskStore.tasks) { _, _ in
            keepValidSelectionDeferred()
        }
    }

    private var filteredTasks: [STTTask] {
        Self.filterTasks(tasks: taskStore.tasks, search: sidebarSearchText)
    }

    private static func filterTasks(tasks: [STTTask], search: String) -> [STTTask] {
        let trimmed = search.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return tasks }

        let tokens = trimmed
            .split(whereSeparator: { $0.isWhitespace })
            .map(String.init)

        let tagTerms = tokens
            .filter { $0.hasPrefix("#") }
            .map { String($0.dropFirst()).trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }
            .filter { !$0.isEmpty }

        let textTerms = tokens
            .filter { !$0.hasPrefix("#") }
            .map { $0.lowercased() }

        return tasks.filter { task in
            let title = task.title.lowercased()
            let transcript = task.transcript.lowercased()
            let matchesText = textTerms.allSatisfy { term in
                title.contains(term) || transcript.contains(term)
            }
            guard matchesText else { return false }
            guard !tagTerms.isEmpty else { return true }
            let lowercasedTags = task.tags.map { $0.lowercased() }
            return tagTerms.allSatisfy { tagTerm in
                lowercasedTags.contains(where: { $0.contains(tagTerm) })
            }
        }
    }

    private func keepValidSelectionDeferred() {
        let search = sidebarSearchText
        DispatchQueue.main.async { [taskStore, controller] in
            let filtered = Self.filterTasks(tasks: taskStore.tasks, search: search)
            guard !filtered.isEmpty else {
                controller.selectedTaskID = nil
                return
            }
            if let selectedID = controller.selectedTaskID,
               filtered.contains(where: { $0.id == selectedID }) {
                return
            }
            controller.selectedTaskID = filtered.first?.id
        }
    }

    // MARK: - Status bar

    private var statusBar: some View {
        HStack(spacing: 10) {
            statusItem(
                symbol: controller.microphoneStatusSymbol,
                text: controller.microphoneStatusText,
                tint: microphoneTint
            )
            Divider().frame(height: 14)
            statusItem(
                symbol: recordingStatusSymbol,
                text: controller.statusText,
                tint: recordingTint
            )
            .accessibilityIdentifier("recordingStatusItem")

            if case .failed = controller.phase {
                Button("Retry") { controller.resetToIdle() }
                    .buttonStyle(.bordered)
                    .controlSize(.small)
            }
            Spacer(minLength: 0)
        }
        .font(.system(size: 12, weight: .medium))
        .padding(.horizontal, 14)
        .padding(.vertical, 8)
        .background(Rectangle().fill(SwissTheme.cardFill.opacity(0.95)))
        .overlay(alignment: .top) {
            Rectangle().fill(SwissTheme.border).frame(height: 1)
        }
        .accessibilityIdentifier("statusBar")
    }

    private func statusItem(symbol: String, text: String, tint: Color) -> some View {
        HStack(spacing: 6) {
            Image(systemName: symbol).foregroundStyle(tint)
            Text(text).lineLimit(1)
        }
    }

    private var microphoneTint: Color {
        switch controller.microphoneStatusSymbol {
        case "mic.fill": return .green
        case "questionmark.circle": return .orange
        default: return .red
        }
    }

    private var recordingStatusSymbol: String {
        switch controller.phase {
        case .idle, .starting:   return "circle.fill"
        case .recording:         return "record.circle.fill"
        case .transcribing:      return "waveform"
        case .refining:          return "sparkles"
        case .completed:         return "checkmark.circle.fill"
        case .failed:            return "xmark.circle.fill"
        }
    }

    private var recordingTint: Color {
        switch controller.phase {
        case .idle, .starting:   return .secondary
        case .recording:         return SwissTheme.accent
        case .transcribing:      return SwissTheme.accent.opacity(0.75)
        case .refining:          return SwissTheme.info
        case .completed:         return .green
        case .failed:            return .red
        }
    }
}

// MARK: - Custom Sidebar

private struct CocoSidebar: View {
    let tasks: [STTTask]
    @Binding var searchText: String
    @Binding var selectedID: UUID?
    let onSettings: () -> Void

    // Group tasks by date label
    private struct DateGroup: Identifiable {
        let id: String
        let label: String
        let tasks: [STTTask]
    }

    private var groups: [DateGroup] {
        let cal = Calendar.current
        let now = Date()
        var buckets: [(label: String, date: Date)] = [
            ("Today",     cal.startOfDay(for: now)),
            ("Yesterday", cal.date(byAdding: .day, value: -1, to: cal.startOfDay(for: now))!),
            ("This Week", cal.date(byAdding: .day, value: -7, to: cal.startOfDay(for: now))!),
        ]
        _ = buckets  // used below

        var result: [DateGroup] = []
        var remaining = tasks

        func label(for task: STTTask) -> String {
            if cal.isDateInToday(task.createdAt)     { return "Today" }
            if cal.isDateInYesterday(task.createdAt) { return "Yesterday" }
            let days = cal.dateComponents([.day], from: cal.startOfDay(for: task.createdAt), to: cal.startOfDay(for: now)).day ?? 0
            if days < 7 { return "This Week" }
            // Older: group by "Month YYYY"
            let formatter = DateFormatter()
            formatter.dateFormat = "MMMM yyyy"
            return formatter.string(from: task.createdAt)
        }

        var grouped: [(String, [STTTask])] = []
        var seen: [String] = []
        for task in remaining {
            let lbl = label(for: task)
            if let idx = grouped.firstIndex(where: { $0.0 == lbl }) {
                grouped[idx].1.append(task)
            } else {
                grouped.append((lbl, [task]))
                seen.append(lbl)
            }
        }
        for (lbl, ts) in grouped {
            result.append(DateGroup(id: lbl, label: lbl, tasks: ts))
        }
        return result
    }

    var body: some View {
        VStack(spacing: 0) {
            // ── Header ────────────────────────────────────────────────────
            HStack(spacing: 6) {
                // Search field
                HStack(spacing: 5) {
                    Image(systemName: "magnifyingglass")
                        .font(.system(size: 10))
                        .foregroundStyle(.tertiary)
                    TextField("Search…", text: $searchText)
                        .textFieldStyle(.plain)
                        .font(.system(size: 12))
                        .foregroundStyle(.primary)
                        .accessibilityIdentifier("sidebarSearch")
                    if !searchText.isEmpty {
                        Button { searchText = "" } label: {
                            Image(systemName: "xmark.circle.fill")
                                .font(.system(size: 10))
                                .foregroundStyle(.tertiary)
                        }
                        .buttonStyle(.plain)
                    }
                }
                .padding(.horizontal, 8)
                .padding(.vertical, 5)
                .background(
                    RoundedRectangle(cornerRadius: 6, style: .continuous)
                        .fill(Color.primary.opacity(0.06))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 6, style: .continuous)
                        .stroke(SwissTheme.border, lineWidth: 1)
                )

                Button(action: onSettings) {
                    Image(systemName: "gearshape")
                        .font(.system(size: 12))
                        .foregroundStyle(.secondary)
                        .frame(width: 26, height: 26)
                        .background(
                            RoundedRectangle(cornerRadius: 6, style: .continuous)
                                .fill(Color.primary.opacity(0.05))
                        )
                }
                .buttonStyle(.plain)
                .help("Settings")
                .accessibilityIdentifier("openSettingsButton")
            }
            .padding(.horizontal, 8)
            .padding(.vertical, 8)
            .background(Color(hex: "1C1E24"))

            Divider()

            // ── Session list ──────────────────────────────────────────────
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 0, pinnedViews: []) {
                        if groups.isEmpty {
                            Text("No results")
                                .font(.system(size: 11))
                                .foregroundStyle(.tertiary)
                                .frame(maxWidth: .infinity)
                                .padding(.top, 32)
                        } else {
                            ForEach(groups) { group in
                                // Date group header
                                Text(group.label.uppercased())
                                    .font(.cocoMono(9.5))
                                    .foregroundStyle(.tertiary)
                                    .tracking(0.06)
                                    .padding(.horizontal, 12)
                                    .padding(.top, 10)
                                    .padding(.bottom, 2)

                                ForEach(group.tasks) { task in
                                    TaskRowView(
                                        task: task,
                                        isSelected: selectedID == task.id
                                    )
                                    .id(task.id)
                                    .contentShape(Rectangle())
                                    .onTapGesture {
                                        selectedID = task.id
                                    }
                                }
                            }
                        }
                    }
                    .padding(.bottom, 8)
                }
                .onChange(of: selectedID) { _, newID in
                    if let id = newID {
                        withAnimation { proxy.scrollTo(id, anchor: .center) }
                    }
                }
            }
        }
        .background(Color(hex: "1C1E24"))
    }
}

