private struct CocoMetaPanel: View {
    let task: STTTask

    @EnvironmentObject private var taskStore: TaskStore
    @EnvironmentObject private var controller: AppController
    @State private var showDeleteConfirmation = false

    var body: some View {
        VStack(spacing: 0) {
            ScrollView {
                VStack(alignment: .leading, spacing: 0) {

                    // ── Title (editable) ──────────────────────────────────
                    VStack(alignment: .leading, spacing: 5) {
                        panelLabel("TITLE")
                        TextField("Task name", text: Binding(
                            get: { taskStore.task(id: task.id)?.title ?? task.title },
                            set: { taskStore.updateTaskTitle(id: task.id, title: $0) }
                        ))
                        .textFieldStyle(.plain)
                        .font(.cocoBody(12, weight: .medium))
                        .foregroundStyle(.primary)
                        .padding(.horizontal, 8)
                        .padding(.vertical, 5)
                        .background(
                            RoundedRectangle(cornerRadius: 5, style: .continuous)
                                .fill(SwissTheme.fieldFill)
                        )
                        .overlay(
                            RoundedRectangle(cornerRadius: 5, style: .continuous)
                                .stroke(SwissTheme.border, lineWidth: 1)
                        )
                    }
                    .padding(.horizontal, 12)
                    .padding(.top, 12)
                    .padding(.bottom, 10)

                    Divider()

                    // ── Metadata ──────────────────────────────────────────
                    VStack(alignment: .leading, spacing: 5) {
                        panelLabel("METADATA")
                        metaRow("Date",   value: task.createdAt.formatted(.dateTime.month().day().hour().minute()))
                        metaRow("Mode",   value: task.mode.displayName)
                        metaRow("Engine", value: task.engine.displayName)
                        metaRow("ID",     value: String(task.id.uuidString.prefix(8)))
                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 10)

                    Divider()

                    // ── Timing ────────────────────────────────────────────
                    VStack(alignment: .leading, spacing: 6) {
                        panelLabel("TIMING")
                        HStack(spacing: 4) {
                            if let dur = task.recordingDurationSeconds, dur > 0 {
                                timingPill("REC " + formatDur(dur),  color: SwissTheme.accent,  bg: SwissTheme.accentDim)
                            }
                            if let dur = task.displayTranscriptionSeconds {
                                timingPill("TRANS " + formatDur(dur), color: SwissTheme.info,    bg: SwissTheme.info.opacity(0.12))
                            }
                            if let dur = task.displayUnderstandingSeconds {
                                timingPill("COMP " + formatDur(dur),  color: SwissTheme.success, bg: SwissTheme.success.opacity(0.12))
                            }
                            if task.recordingDurationSeconds == nil
                               && task.displayTranscriptionSeconds == nil
                               && task.displayUnderstandingSeconds == nil {
                                Text("—").font(.cocoMono(10)).foregroundStyle(.tertiary)
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 10)

                    Divider()

                    // ── Tags ──────────────────────────────────────────────
                    VStack(alignment: .leading, spacing: 6) {
                        panelLabel("TAGS")
                        TagPillInput(
                            tags: Binding(
                                get: { taskStore.task(id: task.id)?.tags ?? task.tags },
                                set: { taskStore.updateTaskTags(id: task.id, tagsCSV: $0.joined(separator: ", ")) }
                            )
