                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 10)

                    Divider()

                    // ── Actions ───────────────────────────────────────────
                    VStack(alignment: .leading, spacing: 6) {
                        panelLabel("ACTIONS")
                        Button {
                            taskStore.toggleTaskFavorited(id: task.id)
                        } label: {
                            actionRow(
                                icon: task.isFavorited ? "star.fill" : "star",
                                label: task.isFavorited ? "Favourited" : "Add to Favourites",
                                color: task.isFavorited ? SwissTheme.accent : .secondary,
                                bg: task.isFavorited ? SwissTheme.accentDim : Color.primary.opacity(0.04),
                                border: task.isFavorited ? SwissTheme.accent.opacity(0.3) : SwissTheme.border
                            )
                        }
                        .buttonStyle(.plain)
                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 10)

                    Divider()

                    // ── Raw Transcript ────────────────────────────────────
                    VStack(alignment: .leading, spacing: 6) {
                        panelLabel("RAW TRANSCRIPT")
                        let rawText = task.rawTranscript ?? task.transcript
                        if rawText.isEmpty {
                            Text("No transcript")
                                .font(.cocoMono(10))
                                .foregroundStyle(.tertiary)
                                .italic()
                        } else {
                            Text(rawText)
                                .font(.cocoMono(10))
                                .foregroundStyle(.secondary)
                                .lineSpacing(2)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .textSelection(.enabled)
                        }
                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 10)

                    Spacer(minLength: 16)
                }
            }

            // ── Bottom pinned actions ─────────────────────────────────────
            VStack(spacing: 6) {
                Divider()
                Button {
                    saveTranscriptToFile(task.transcript, title: task.title)
                } label: {
                    actionRow(
                        icon: "arrow.down.doc",
                        label: "Save to File",
                        color: .secondary,
                        bg: Color.primary.opacity(0.04),
                        border: SwissTheme.border
                    )
                }
                .buttonStyle(.plain)
                .padding(.horizontal, 12)

                Button(role: .destructive) {
                    showDeleteConfirmation = true
                } label: {
                    actionRow(
                        icon: "trash",
                        label: "Delete Task",
                        color: .red.opacity(0.75),
                        bg: Color.red.opacity(0.06),
                        border: Color.red.opacity(0.15)
                    )
                }
                .buttonStyle(.plain)
                .padding(.horizontal, 12)
                .padding(.bottom, 10)
            }
        }
        .background(Color(hex: "1C1E24").opacity(0.6))
        .alert("Delete This Task?", isPresented: $showDeleteConfirmation) {
            Button("Cancel", role: .cancel) { }
            Button("Delete", role: .destructive) { deleteTask() }
        } message: {
            Text("This will remove the task and its audio file. This action cannot be undone.")
        }
    }

    // MARK: - Sub-views

    private func panelLabel(_ text: String) -> some View {
        Text(text)
            .font(.system(size: 9.5, weight: .semibold))
            .tracking(0.08)
            .foregroundStyle(.secondary)
    }

    private func metaRow(_ key: String, value: String) -> some View {
        HStack(alignment: .top, spacing: 6) {
            Text(key)
                .font(.cocoMono(10))
                .foregroundStyle(.secondary)
                .frame(width: 46, alignment: .leading)
            Text(value)
                .font(.cocoMono(10))
                .foregroundStyle(.primary)
                .lineLimit(2)
                .fixedSize(horizontal: false, vertical: true)
                .frame(maxWidth: .infinity, alignment: .leading)
        }
    }

    private func timingPill(_ label: String, color: Color, bg: Color) -> some View {
        Text(label)
            .font(.cocoMono(9))
            .foregroundStyle(color)
            .padding(.horizontal, 6)
            .padding(.vertical, 2)
            .background(Capsule().fill(bg))
            .overlay(Capsule().stroke(color.opacity(0.25), lineWidth: 1))
    }

    private func actionRow(icon: String, label: String, color: Color, bg: Color, border: Color) -> some View {
        HStack(spacing: 6) {
            Image(systemName: icon)
                .font(.system(size: 11))
                .foregroundStyle(color)
                .frame(width: 14)
            Text(label)
                .font(.system(size: 11.5))
                .foregroundStyle(color)
            Spacer()
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 6)
        .background(RoundedRectangle(cornerRadius: 6, style: .continuous).fill(bg))
        .overlay(RoundedRectangle(cornerRadius: 6, style: .continuous).stroke(border, lineWidth: 1))
    }

    private func formatDur(_ seconds: Double) -> String {
        let m = Int(seconds) / 60
        let s = Int(seconds) % 60
        return String(format: "%d:%02d", m, s)
    }

    private func deleteTask() {
        let next = taskStore.preferredTaskSelectionAfterDeleting(id: task.id)
        taskStore.deleteTask(id: task.id)
        controller.selectedTaskID = next
    }

    private func saveTranscriptToFile(_ transcript: String, title: String) {
        let panel = NSSavePanel()
        panel.allowedContentTypes = [.plainText]
        panel.canCreateDirectories = true
        panel.nameFieldStringValue = "\(title).txt"
        panel.title = "Save Transcript"
        if panel.runModal() == .OK, let url = panel.url {
            try? transcript.write(to: url, atomically: true, encoding: .utf8)
        }
    }
}

// MARK: - Tag Pill Input

private struct TagPillInput: View {
    @Binding var tags: [String]
    @State private var input = ""
    @FocusState private var isFocused: Bool

    private let separatorSet = CharacterSet(charactersIn: ",，;\n")

    var body: some View {
        ZStack(alignment: .leading) {
            RoundedRectangle(cornerRadius: 6, style: .continuous)
                .fill(SwissTheme.fieldFill)
                .overlay(
                    RoundedRectangle(cornerRadius: 6, style: .continuous)
                        .stroke(isFocused ? SwissTheme.accent.opacity(0.8) : SwissTheme.border, lineWidth: 1)
                )
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 5) {
                    ForEach(tags, id: \.self) { tag in
                        SwissRemovableTagPill(text: tag) { removeTag(tag) }
                    }
                    TextField(tags.isEmpty ? "Add tag…" : "More…", text: $input)
                        .textFieldStyle(.plain)
                        .focused($isFocused)
                        .frame(minWidth: 55)
                        .font(.system(size: 11))
                        .onChange(of: input) { _, v in tokenizeInputIfNeeded(v) }
                        .onSubmit { commitCurrentInput() }
                }
            }
            .padding(.horizontal, 8)
            .padding(.vertical, 5)
        }
        .frame(height: 30)
        .contentShape(Rectangle())
        .onTapGesture { isFocused = true }
    }

    private func tokenizeInputIfNeeded(_ value: String) {
        guard value.rangeOfCharacter(from: separatorSet) != nil else { return }
        let parts = value.components(separatedBy: separatorSet)
        if parts.count > 1 { parts.dropLast().forEach { appendTag($0) } }
        input = parts.last ?? ""
    }

    private func commitCurrentInput() { appendTag(input); input = "" }

    private func appendTag(_ raw: String) {
        let c = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !c.isEmpty, !tags.contains(c) else { return }
        tags.append(c)
    }

    private func removeTag(_ tag: String) { tags.removeAll { $0 == tag } }
}

