import Foundation

/// Builds a minimal .app bundle from the SPM debug binary so XCUIApplication can launch it.
///
/// Call `try AppBundleBuilder.buildIfNeeded()` in `XCTestCase.setUpWithError()`.
/// The bundle is written to `/tmp/CocoScribeUITests.app` and reused across test runs
/// unless the source binary is newer.
enum AppBundleBuilder {
    static let bundleID = "com.harveyzhang96.macstttool"
    static let appName  = "CocoScribe"

    static var appBundleURL: URL {
        URL(fileURLWithPath: "/tmp/CocoScribeUITests.app")
    }

    // MARK: - Build

    /// Creates (or refreshes) the .app bundle and returns its URL.
    @discardableResult
    static func buildIfNeeded() throws -> URL {
        let binaryURL = try findDebugBinary()
        let bundleURL = appBundleURL
        let macOSDir  = bundleURL.appendingPathComponent("Contents/MacOS")
        let destBin   = macOSDir.appendingPathComponent(appName)
        let plistURL  = bundleURL.appendingPathComponent("Contents/Info.plist")

        // Skip rebuild if bundle binary is newer than the source binary.
        if FileManager.default.fileExists(atPath: destBin.path),
           let srcDate  = modDate(binaryURL),
           let destDate = modDate(destBin),
           destDate >= srcDate {
            return bundleURL
        }

        // (Re)create the bundle structure.
        try? FileManager.default.removeItem(at: bundleURL)
        try FileManager.default.createDirectory(at: macOSDir, withIntermediateDirectories: true)
        try FileManager.default.copyItem(at: binaryURL, to: destBin)
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: destBin.path)
        try infoPlistContent.write(to: plistURL, atomically: true, encoding: .utf8)

        // Ad-hoc sign so macOS will run it.
        let sign = Process()
        sign.executableURL = URL(fileURLWithPath: "/usr/bin/codesign")
        sign.arguments = ["--force", "--deep", "--sign", "-", bundleURL.path]
        try sign.run()
        sign.waitUntilExit()

        return bundleURL
    }

    // MARK: - Private

    /// Locates the SPM debug binary by walking up from the current working directory
    /// until a `Package.swift` is found, then appending `.build/debug/MacSTTTool`.
    private static func findDebugBinary() throws -> URL {
        var dir = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
        for _ in 0..<10 {
            let marker = dir.appendingPathComponent("Package.swift")
            if FileManager.default.fileExists(atPath: marker.path) {
                let binary = dir.appendingPathComponent(".build/debug/MacSTTTool")
                if FileManager.default.fileExists(atPath: binary.path) {
                    return binary
                }
                // Binary not yet built — give a helpful error.
                throw NSError(
                    domain: "AppBundleBuilder",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey:
                        "Debug binary not found at \(binary.path). Run `swift build` first."]
                )
            }
            let parent = dir.deletingLastPathComponent()
            if parent == dir { break }
            dir = parent
        }
        throw NSError(
            domain: "AppBundleBuilder",
            code: 2,
            userInfo: [NSLocalizedDescriptionKey:
                "Could not find Package.swift walking up from \(FileManager.default.currentDirectoryPath)"]
        )
    }

    private static func modDate(_ url: URL) -> Date? {
        try? FileManager.default.attributesOfItem(atPath: url.path)[.modificationDate] as? Date
    }

    private static var infoPlistContent: String {
        """
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "https://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0">
        <dict>
            <key>CFBundleExecutable</key>
            <string>\(appName)</string>
            <key>CFBundleIdentifier</key>
            <string>\(bundleID)</string>
            <key>CFBundleName</key>
            <string>\(appName)</string>
            <key>CFBundlePackageType</key>
            <string>APPL</string>
            <key>CFBundleShortVersionString</key>
            <string>5.0.0</string>
            <key>CFBundleVersion</key>
            <string>500</string>
            <key>LSMinimumSystemVersion</key>
            <string>14.0</string>
            <key>LSUIElement</key>
            <true/>
            <key>NSMicrophoneUsageDescription</key>
            <string>CocoScribe UITest</string>
        </dict>
        </plist>
        """
    }
}

