import Foundation

enum RecordingMode: String, Codable {
    case transcribe
    case comprehend
    case continuous
    case continuousComprehend = "continuous_comprehend"

    var displayName: String {
        switch self {
        case .transcribe:           return "TRANSCRIBE"
        case .comprehend:           return "COMPREHEND"
        case .continuous:           return "CONTINUOUS"
        case .continuousComprehend: return "CONT.COMPREHEND"
        }
    }
}

enum TranscriptionEngineKind: String, Codable, CaseIterable, Identifiable {
    case whisperCpp = "whisper_cpp"
    case openAI = "openai_compatible"
    case mlxOpenAIServer = "mlx_openai_server"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .whisperCpp:
            return "whisper.cpp"
        case .openAI:
            return "External API"
        case .mlxOpenAIServer:
            return "mlx-openai-server"
        }
    }
}

struct STTTask: Identifiable, Codable, Hashable {
    var id: UUID
    var title: String
    var tags: [String]
    var createdAt: Date
    var updatedAt: Date
    var audioFilePath: String
    var transcript: String
    var rawTranscript: String?
    var engine: TranscriptionEngineKind
    var mode: RecordingMode
    var isFavorited: Bool
    var recordingDurationSeconds: Double?
    var transcriptionDurationSeconds: Double?
    var understandingDurationSeconds: Double?
    /// 从录音结束到任务完成的 wall clock 时长（秒）。
    var postRecordingDurationSeconds: Double?
    /// 扁平化的 pipeline metrics，如 `pipeline.metrics.transcription.total_ms`。
    var pipelineMetrics: [String: Double]?

    init(
        id: UUID = UUID(),
        title: String,
        tags: [String] = [],
        createdAt: Date = Date(),
        updatedAt: Date = Date(),
        audioFilePath: String,
        transcript: String,
        rawTranscript: String? = nil,
        engine: TranscriptionEngineKind,
        mode: RecordingMode = .transcribe,
        isFavorited: Bool = false,
        recordingDurationSeconds: Double? = nil,
        transcriptionDurationSeconds: Double? = nil,
        understandingDurationSeconds: Double? = nil,
        postRecordingDurationSeconds: Double? = nil,
        pipelineMetrics: [String: Double]? = nil
    ) {
        self.id = id
        self.title = title
        self.tags = tags
        self.createdAt = createdAt
        self.updatedAt = updatedAt
        self.audioFilePath = audioFilePath
        self.transcript = transcript
        self.rawTranscript = rawTranscript
        self.engine = engine
        self.mode = mode
        self.isFavorited = isFavorited
        self.recordingDurationSeconds = recordingDurationSeconds
        self.transcriptionDurationSeconds = transcriptionDurationSeconds
        self.understandingDurationSeconds = understandingDurationSeconds
        self.postRecordingDurationSeconds = postRecordingDurationSeconds
        self.pipelineMetrics = pipelineMetrics
    }
}

extension STTTask {
    private enum CodingKeys: String, CodingKey {
        case id
        case title
        case tags
        case createdAt
        case updatedAt
        case audioFilePath
        case transcript
        case rawTranscript
        case engine
        case mode
        case isFavorited
        case recordingDurationSeconds
        case transcriptionDurationSeconds
        case understandingDurationSeconds
        case postRecordingDurationSeconds
        case pipelineMetrics
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        id = try container.decode(UUID.self, forKey: .id)
        title = try container.decode(String.self, forKey: .title)
        tags = try container.decodeIfPresent([String].self, forKey: .tags) ?? []
        createdAt = try container.decode(Date.self, forKey: .createdAt)
        updatedAt = try container.decode(Date.self, forKey: .updatedAt)
        audioFilePath = try container.decode(String.self, forKey: .audioFilePath)
        transcript = try container.decode(String.self, forKey: .transcript)
        rawTranscript = try container.decodeIfPresent(String.self, forKey: .rawTranscript)
        engine = try container.decode(TranscriptionEngineKind.self, forKey: .engine)
        mode = try container.decodeIfPresent(RecordingMode.self, forKey: .mode) ?? .transcribe
        isFavorited = try container.decodeIfPresent(Bool.self, forKey: .isFavorited) ?? false
        recordingDurationSeconds = try container.decodeIfPresent(Double.self, forKey: .recordingDurationSeconds)
        transcriptionDurationSeconds = try container.decodeIfPresent(Double.self, forKey: .transcriptionDurationSeconds)
        understandingDurationSeconds = try container.decodeIfPresent(Double.self, forKey: .understandingDurationSeconds)
        postRecordingDurationSeconds = try container.decodeIfPresent(Double.self, forKey: .postRecordingDurationSeconds)
        pipelineMetrics = try container.decodeIfPresent([String: Double].self, forKey: .pipelineMetrics)
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(id, forKey: .id)
        try container.encode(title, forKey: .title)
        try container.encode(tags, forKey: .tags)
        try container.encode(createdAt, forKey: .createdAt)
        try container.encode(updatedAt, forKey: .updatedAt)
        try container.encode(audioFilePath, forKey: .audioFilePath)
        try container.encode(transcript, forKey: .transcript)
        try container.encodeIfPresent(rawTranscript, forKey: .rawTranscript)
        try container.encode(engine, forKey: .engine)
        try container.encode(mode, forKey: .mode)
        try container.encode(isFavorited, forKey: .isFavorited)
        try container.encodeIfPresent(recordingDurationSeconds, forKey: .recordingDurationSeconds)
        try container.encodeIfPresent(transcriptionDurationSeconds, forKey: .transcriptionDurationSeconds)
        try container.encodeIfPresent(understandingDurationSeconds, forKey: .understandingDurationSeconds)
        try container.encodeIfPresent(postRecordingDurationSeconds, forKey: .postRecordingDurationSeconds)
        try container.encodeIfPresent(pipelineMetrics, forKey: .pipelineMetrics)
    }
}

extension STTTask {
    /// Returns "M:SS" for valid seconds, nil for nil/NaN/<0.
    private static func formatMSS(seconds: Double?) -> String? {
        guard let s = seconds, !s.isNaN, s >= 0 else { return nil }
        let total = Int(round(s))
        let minutes = total / 60
        let secs = total % 60
        return String(format: "%d:%02d", minutes, secs)
    }

    /// Formats `recordingDurationSeconds` as "M:SS" or "MM:SS"; returns "–" when nil or invalid.
    static func formattedRecordingDuration(seconds: Double?) -> String {
        formatMSS(seconds: seconds) ?? "–"
    }

    /// Returns "LABEL M:SS" when seconds is valid, or "–" when nil, NaN, or < 0.
    static func formattedDuration(label: String, seconds: Double?) -> String {
        guard let time = formatMSS(seconds: seconds) else { return "–" }
        return "\(label) \(time)"
    }

    // MARK: - Pipeline metrics 作为展示来源（Task 5：统一时长视图）

    /// 用于 UI 展示的转录阶段时长（秒）。优先来自 pipeline.metrics.transcription.total_ms，否则用旧字段。
    var displayTranscriptionSeconds: Double? {
        pipelineMetrics?["pipeline.metrics.transcription.total_ms"].map { $0 / 1000 }
            ?? transcriptionDurationSeconds
    }

    /// 用于 UI 展示的理解/文本处理阶段时长（秒）。优先来自 pipeline.metrics.textProcessing.total_ms，否则用旧字段。
    var displayUnderstandingSeconds: Double? {
        pipelineMetrics?["pipeline.metrics.textProcessing.total_ms"].map { $0 / 1000 }
            ?? understandingDurationSeconds
    }

    static func defaultTitle(for date: Date, id: UUID, mode: RecordingMode = .transcribe) -> String {
        let shortID = id.uuidString
            .split(separator: "-")
            .first
            .map(String.init)?
            .uppercased() ?? id.uuidString.uppercased()
        switch mode {
        case .transcribe, .continuous:
            return "TR-\(shortID)"
        case .comprehend, .continuousComprehend:
            return "CP-\(shortID)"
        }
    }
}

