    private let session: RecordingSession
    private let clipboard: Clipboard
    private let hotkeyManager: GlobalHotkeyRegistering?
    private let transcriptionFlow: TranscriptionFlow
    private let vadCoordinator: VADSessionCoordinator
    private let pipelines: [PipelineID: PipelineConfiguration]
    private var activePipelineID: PipelineID = .recordAndTranscribe
    private var cancellables = Set<AnyCancellable>()
    /// Captured when user triggers recording via hotkey (to paste back into that app when done).
    private var frontmostAppWhenHotkeyTriggered: NSRunningApplication?

    private static let logger = Logger(subsystem: "com.macstttool.app", category: "flow")

    init(
        taskStore: TaskStore,
        settingsStore: SettingsStore,
        audioRecorder: AudioRecording,
        clipboard: Clipboard,
        hotkeyManager: GlobalHotkeyRegistering?,
        transcriptionService: TranscriptionServiceProtocol,
        textProcessors: [TextProcessingServiceProtocol] = [],
        vadCoordinator: VADSessionCoordinator
    ) {
        self.taskStore = taskStore
        self.settingsStore = settingsStore
        self.session = RecordingSession(audioRecorder: audioRecorder)
        self.clipboard = clipboard
        self.hotkeyManager = hotkeyManager
        self.transcriptionFlow = TranscriptionFlow(
            transcriptionService: transcriptionService,
            textProcessors: textProcessors
        )
        self.vadCoordinator = vadCoordinator
        self.pipelines = [
            .recordAndTranscribe: .recordAndTranscribe(),
            .recordTranscribeAndRefine: .recordTranscribeAndRefine()
        ]

        vadCoordinator.onPhaseChange = { [weak self] newPhase in
            self?.phase = newPhase
            if case .completed = newPhase { self?.scheduleResetToIdle() }
        }

        vadCoordinator.onRecordingDurationUpdate = { [weak self] seconds in
            self?.recordingDurationSeconds = seconds
        }

        vadCoordinator.onSessionCompleted = { [weak self] result, triggeredFromHotkey in
            self?.handleSessionResult(result, triggeredFromHotkey: triggeredFromHotkey)
        }

        vadCoordinator.onIncrementalTranscript = { [weak self] transcript in
            guard let self, self.settingsStore.settings.autoCopyToClipboard else { return }
            self.clipboard.copy(text: transcript)
        }

        session.$recordingDurationSeconds
            .receive(on: DispatchQueue.main)
            .sink { [weak self] value in
                self?.recordingDurationSeconds = value
            }
            .store(in: &cancellables)

        session.$audioLevel
            .receive(on: DispatchQueue.main)
            .sink { [weak self] value in
                self?.audioLevel = value
            }
            .store(in: &cancellables)

        settingsStore.$settings
            .map { settings in
                HotkeyBindings(
                    recording: settings.hotkey,
                    openHistory: settings.openHistoryHotkey,
                    openSettings: settings.openSettingsHotkey,
                    understandingMode: settings.understandingModeHotkey,
                    vadMode: settings.vadHotkey,
                    vadComprehendMode: settings.vadComprehendHotkey
                )
            }
            .removeDuplicates()
            .sink { [weak self] hotkeys in
                self?.registerHotkeys(
                    recording: hotkeys.recording,
                    openHistory: hotkeys.openHistory,
                    openSettings: hotkeys.openSettings,
                    understandingMode: hotkeys.understandingMode,
                    vadMode: hotkeys.vadMode,
                    vadComprehendMode: hotkeys.vadComprehendMode
                )
            }
            .store(in: &cancellables)

        if hotkeyManager == nil {
            phase = .failed(TranscriptionFailure(reason: "Global hotkey is unavailable in this session."))
        } else {
            registerHotkeys(
                recording: settingsStore.settings.hotkey,
                openHistory: settingsStore.settings.openHistoryHotkey,
                openSettings: settingsStore.settings.openSettingsHotkey,
                understandingMode: settingsStore.settings.understandingModeHotkey,
                vadMode: settingsStore.settings.vadHotkey,
                vadComprehendMode: settingsStore.settings.vadComprehendHotkey
            )
        }

        Task { @MainActor [weak self] in
            await self?.requestMicrophonePermissionOnFirstLaunchIfNeeded()
        }
    }

