        case .transcribing:
            return "transcribing"
        case .refining:
            return "refining"
        case .completed:
            return "completed"
        case .failed(let failure):
            return "failed-\(failure.reason.hashValue)"
        }
    }

    var statusText: String {
        switch phase {
        case .idle:
            return "Idle"
        case .starting:
