    func toggleRecordingFromUI() {
        Task { @MainActor in
            activePipelineID = .recordAndTranscribe
            await toggleRecording(triggeredFromHotkey: false)
        }
    }

    func toggleRecordingWithUnderstandingModeFromUI() {
        Task { @MainActor in
            activePipelineID = .recordTranscribeAndRefine
            await toggleRecordingWithUnderstandingMode(triggeredFromHotkey: false)
        }
    }

    func toggleVADFromUI() {
        Task { @MainActor in
            await vadCoordinator.toggle(understandingMode: false, triggeredFromHotkey: false)
        }
    }

    func toggleVADComprehendFromUI() {
        Task { @MainActor in
            await vadCoordinator.toggle(understandingMode: true, triggeredFromHotkey: false)
        }
    }

    func showHistoryPage() {
        mainPage = .history
    }

    func showSettingsPage() {
        mainPage = .settings
    }

    func hotkeyHint() -> String {
        let hotkey = settingsStore.settings.hotkey
        return "Global Hotkey keyCode=\(hotkey.keyCode), modifiers=\(hotkey.modifiers)"
    }

    func copyToClipboard(_ text: String) {
        clipboard.copy(text: text)
    }

    /// 将 phase 重置为 idle，供失败时 UI「重试」使用。
    func resetToIdle() {
        phase = .idle
    }

    func refineTaskWithUnderstandingMode(taskID: UUID) async {
        guard phase != .starting, phase != .recording, phase != .transcribing, phase != .refining else { return }
        guard let task = taskStore.task(id: taskID) else { return }
        let audioURL = URL(fileURLWithPath: task.audioFilePath)
        guard FileManager.default.fileExists(atPath: audioURL.path) else {
            phase = .failed(TranscriptionFailure(reason: "Audio file no longer exists. Cannot re-transcribe."))
            Self.logger.error("refine: audio file missing")
            scheduleResetToIdle()
            return
        }

        activePipelineID = .recordTranscribeAndRefine
        phase = .transcribing
        let currentSettings = settingsStore.settings
        Self.logger.info("understanding mode (refine) started, taskID=\(taskID.uuidString)")

        do {
            let pipeline = pipelines[activePipelineID] ?? .recordTranscribeAndRefine()
            let orderedStages = pipeline.orderedStageIDs()
            let shouldRunTextProcessing = orderedStages.contains("textProcessing")

            let result = try await transcriptionFlow.run(
                audioURL: audioURL,
                settings: currentSettings,
                understandingMode: shouldRunTextProcessing
            )
            if shouldRunTextProcessing,
               result.understandingDurationSeconds != nil {
                // "理解中"至少展示一段时间，避免 phase 切换过快导致 menu bar pill 完全看不到。
                phase = .refining
                try? await Task.sleep(nanoseconds: UInt64(AppConstants.minRefiningDisplaySeconds * 1_000_000_000))
            }
            taskStore.updateTranscript(id: taskID, transcript: result.transcript, transcriptionDurationSeconds: result.transcriptionDurationSeconds, understandingDurationSeconds: result.understandingDurationSeconds)
            phase = .completed
            Self.logger.info("understanding mode (refine) completed")
            scheduleResetToIdle()
        } catch {
            phase = .failed(TranscriptionFailure(from: error))
            Self.logger.error("understanding mode (refine) failed: \(error.localizedDescription)")
        }
    }

    private func toggleRecording(triggeredFromHotkey: Bool) async {
        switch phase {
        case .recording:
            await stopRecordingAndTranscribe(triggeredFromHotkey: triggeredFromHotkey)
        case .starting, .transcribing, .refining:
            break
        default:
            await startRecording(understandingMode: false)
        }
    }

    private func toggleRecordingWithUnderstandingMode(triggeredFromHotkey: Bool) async {
        switch phase {
        case .recording:
            await stopRecordingAndTranscribe(triggeredFromHotkey: triggeredFromHotkey)
        case .starting, .transcribing, .refining:
            break
        default:
            activePipelineID = .recordTranscribeAndRefine
            await startRecording(understandingMode: true)
        }
    }

    private func startRecording(understandingMode: Bool) async {
        // Set .starting synchronously before any await to prevent reentrant hotkey presses
        // from also entering startRecording while the audio engine is initializing.
        phase = .starting
        let retryPermissionWhenDenied =
            settingsStore.settings.hasRequestedMicrophonePermissionOnFirstLaunch &&
            !settingsStore.settings.didGrantMicrophonePermissionOnFirstLaunch
        do {
            try await session.start(understandingMode: understandingMode, retryPermissionWhenDenied: retryPermissionWhenDenied)
            phase = .recording
            Self.logger.info("recording started, understandingMode=\(understandingMode)")
        } catch {
            _ = session.stop()
            phase = .failed(TranscriptionFailure(from: error))
            Self.logger.error("recording start failed: \(error.localizedDescription)")
        }
    }

    private func stopRecordingAndTranscribe(triggeredFromHotkey: Bool) async {
        guard let audioURL = session.stop() else {
            phase = .failed(TranscriptionFailure(reason: "No recording file found."))
            Self.logger.error("recording stop: no file")
            return
        }
        let understandingModeFlag = session.lastRecordingUnderstandingMode
        let postRecordingStart = Date()
        Self.logger.info("recording stopped, understandingMode=\(understandingModeFlag)")

        phase = .transcribing
        let currentSettings = settingsStore.settings
        Self.logger.info("transcription started")

        // 构建当前运行所需的 pipeline 配置与 metrics collector。
        let pipeline = pipelines[activePipelineID] ?? .recordAndTranscribe()
        let stagesByID = Dictionary(uniqueKeysWithValues: pipeline.stages.map { ($0.id, $0) })
        let metricsCollector = PipelineMetricsCollector()

        let transcriptionStage = stagesByID["transcription"]
        let transcriptionContext: StageContext? = transcriptionStage.map {
            StageContext(
                stageID: $0.id,
                metricsConfig: $0.metrics,
                metricsKey: $0.metrics?.metricsKey ?? $0.id,
                metricsCollector: metricsCollector
            )
        }

        let textProcessingStage = stagesByID["textProcessing"]
        let textProcessingContext: StageContext? = textProcessingStage.map {
            StageContext(
                stageID: $0.id,
                metricsConfig: $0.metrics,
                metricsKey: $0.metrics?.metricsKey ?? $0.id,
                metricsCollector: metricsCollector
            )
        }

        do {
            let orderedStages = pipeline.orderedStageIDs()
            let shouldRunTextProcessing = orderedStages.contains("textProcessing")

            let result = try await transcriptionFlow.run(
                audioURL: audioURL,
                settings: currentSettings,
                understandingMode: shouldRunTextProcessing,
                transcriptionContext: transcriptionContext,
                textProcessingContext: shouldRunTextProcessing ? textProcessingContext : nil
            )

            var recordingDurationSeconds: Double?
            do {
                let asset = AVURLAsset(url: audioURL)
                let duration = try await asset.load(.duration)
                let seconds = CMTimeGetSeconds(duration)
                if !seconds.isNaN, seconds >= 0 {
                    recordingDurationSeconds = seconds
                }
            } catch {
                recordingDurationSeconds = nil
            }

            let pipelineMetrics = metricsCollector.exportFlatMetrics()
            let transcriptionSec = pipelineMetrics["pipeline.metrics.transcription.total_ms"].map { $0 / 1000 }
            let understandingSec = pipelineMetrics["pipeline.metrics.textProcessing.total_ms"].map { $0 / 1000 }
            let postRecordingSec = Date().timeIntervalSince(postRecordingStart)

            let sessionResult = SessionResult(
                transcript: result.transcript,
                rawTranscript: result.rawTranscript,
                audioURL: audioURL,
                mode: activePipelineID == .recordTranscribeAndRefine ? .comprehend : .transcribe,
                engine: currentSettings.selectedEngine,
                recordingDurationSeconds: recordingDurationSeconds,
                transcriptionDurationSeconds: transcriptionSec ?? result.transcriptionDurationSeconds,
                understandingDurationSeconds: understandingSec ?? result.understandingDurationSeconds,
                postRecordingDurationSeconds: postRecordingSec >= 0 ? postRecordingSec : nil,
                pipelineMetrics: pipelineMetrics.isEmpty ? nil : pipelineMetrics,
                suggestedTitle: result.suggestedTitle
            )
            handleSessionResult(sessionResult, triggeredFromHotkey: triggeredFromHotkey)

            if shouldRunTextProcessing,
               result.understandingDurationSeconds != nil {
                // "理解中"至少展示一段时间，避免 phase 切换过快导致 menu bar pill 完全看不到。
                phase = .refining
                try? await Task.sleep(nanoseconds: UInt64(AppConstants.minRefiningDisplaySeconds * 1_000_000_000))
            }

            phase = .completed
            Self.logger.info("transcription completed")
            scheduleResetToIdle()
        } catch {
            phase = .failed(TranscriptionFailure(from: error))
            Self.logger.error("transcription failed: \(error.localizedDescription)")
        }
    }

    /// 两套架构（单次与 VAD）的统一输出路径：持久化任务 + 剪贴板写入/自动粘贴。
    private func handleSessionResult(_ result: SessionResult, triggeredFromHotkey: Bool) {
        let task = taskStore.addTask(
            transcript: result.transcript,
            rawTranscript: result.rawTranscript,
            audioURL: result.audioURL,
            engine: result.engine,
            mode: result.mode,
            title: result.suggestedTitle,
            recordingDurationSeconds: result.recordingDurationSeconds,
            transcriptionDurationSeconds: result.transcriptionDurationSeconds,
            understandingDurationSeconds: result.understandingDurationSeconds,
            postRecordingDurationSeconds: result.postRecordingDurationSeconds,
            pipelineMetrics: result.pipelineMetrics
        )
        selectedTaskID = task.id

        guard settingsStore.settings.autoCopyToClipboard else { return }
        clipboard.copy(text: result.transcript)
        guard settingsStore.settings.autoPasteAfterCopy, triggeredFromHotkey else { return }
        let pid = frontmostAppWhenHotkeyTriggered?.processIdentifier
        frontmostAppWhenHotkeyTriggered = nil
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 250_000_000)
            if self.clipboard.isAccessibilityPermissionGranted() {
                if let pid {
                    self.clipboard.pasteToApp(processIdentifier: pid)
                } else {
                    self.clipboard.pasteToFrontmostApp()
                }
            } else {
                _ = self.clipboard.requestAccessibilityPermissionIfNeeded(prompt: false)
            }
        }
    }

    private func scheduleResetToIdle() {
        Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: 1_000_000_000)
            guard let self else { return }
            if self.phase == .completed {
                self.phase = .idle
            }
        }
    }

    private func registerHotkeys(
        recording: HotkeyConfiguration,
        openHistory: HotkeyConfiguration?,
        openSettings: HotkeyConfiguration?,
        understandingMode: HotkeyConfiguration?,
        vadMode: HotkeyConfiguration? = nil,
        vadComprehendMode: HotkeyConfiguration? = nil
    ) {
        guard let hotkeyManager else { return }
        do {
            try hotkeyManager.register(
                keyCode: recording.keyCode,
                modifiers: recording.modifiers,
                id: HotkeyActionID.recording
            ) { [weak self] in
                Task { @MainActor in
                    if self?.phase != .recording {
                        self?.frontmostAppWhenHotkeyTriggered = NSWorkspace.shared.frontmostApplication
                    }
                    await self?.toggleRecording(triggeredFromHotkey: true)
                }
            }

            if let openHistory {
                try hotkeyManager.register(
                    keyCode: openHistory.keyCode,
                    modifiers: openHistory.modifiers,
                    id: HotkeyActionID.openHistory
                ) { [weak self] in
                    Task { @MainActor in
                        self?.showHistoryFromHotkey()
                    }
                }
            } else {
                hotkeyManager.unregister(id: HotkeyActionID.openHistory)
            }

            if let openSettings {
                try hotkeyManager.register(
                    keyCode: openSettings.keyCode,
                    modifiers: openSettings.modifiers,
                    id: HotkeyActionID.openSettings
                ) { [weak self] in
                    Task { @MainActor in
                        self?.showSettingsFromHotkey()
                    }
                }
            } else {
                hotkeyManager.unregister(id: HotkeyActionID.openSettings)
            }

            if let understandingMode {
                try hotkeyManager.register(
                    keyCode: understandingMode.keyCode,
                    modifiers: understandingMode.modifiers,
                    id: HotkeyActionID.understandingMode
                ) { [weak self] in
                    Task { @MainActor in
                        if self?.phase != .recording {
                            self?.frontmostAppWhenHotkeyTriggered = NSWorkspace.shared.frontmostApplication
                        }
                        await self?.toggleRecordingWithUnderstandingMode(triggeredFromHotkey: true)
                    }
                }
            } else {
                hotkeyManager.unregister(id: HotkeyActionID.understandingMode)
            }

            if let vadMode {
                try hotkeyManager.register(
                    keyCode: vadMode.keyCode,
                    modifiers: vadMode.modifiers,
                    id: HotkeyActionID.vadMode
                ) { [weak self] in
                    Task { @MainActor in
                        if self?.phase != .recording {
                            let app = NSWorkspace.shared.frontmostApplication
                            self?.frontmostAppWhenHotkeyTriggered = app
                            self?.vadCoordinator.frontmostApp = app
                        }
                        await self?.vadCoordinator.toggle(understandingMode: false, triggeredFromHotkey: true)
                    }
                }
            } else {
                hotkeyManager.unregister(id: HotkeyActionID.vadMode)
            }

            if let vadComprehendMode {
                try hotkeyManager.register(
                    keyCode: vadComprehendMode.keyCode,
                    modifiers: vadComprehendMode.modifiers,
                    id: HotkeyActionID.vadComprehendMode
                ) { [weak self] in
                    Task { @MainActor in
                        if self?.phase != .recording {
                            let app = NSWorkspace.shared.frontmostApplication
                            self?.frontmostAppWhenHotkeyTriggered = app
                            self?.vadCoordinator.frontmostApp = app
                        }
                        await self?.vadCoordinator.toggle(understandingMode: true, triggeredFromHotkey: true)
                    }
                }
            } else {
                hotkeyManager.unregister(id: HotkeyActionID.vadComprehendMode)
            }
        } catch {
            hotkeyManager.unregister()
            registerFallbackRecordingHotkey(on: hotkeyManager)
            phase = .failed(TranscriptionFailure(from: error))
            Self.logger.error("hotkey registration failed: \(error.localizedDescription)")
        }
    }

    private func registerFallbackRecordingHotkey(on hotkeyManager: GlobalHotkeyRegistering) {
        do {
            let fallback = settingsStore.settings.hotkey
            try hotkeyManager.register(
                keyCode: fallback.keyCode,
                modifiers: fallback.modifiers,
                id: HotkeyActionID.recording
            ) { [weak self] in
                Task { @MainActor in
                    if self?.phase != .recording {
                        self?.frontmostAppWhenHotkeyTriggered = NSWorkspace.shared.frontmostApplication
                    }
                    await self?.toggleRecording(triggeredFromHotkey: true)
                }
            }
        } catch {
            // Keep the phase error from the failed registration path.
        }
    }

    private func showHistoryFromHotkey() {
        showHistoryPage()
        NotificationCenter.default.post(name: .openHistoryWindowFromHotkey, object: nil)
        NSApp.activate(ignoringOtherApps: true)
    }

    private func showSettingsFromHotkey() {
        showSettingsPage()
        NotificationCenter.default.post(name: .openSettingsWindowFromHotkey, object: nil)
        NSApp.activate(ignoringOtherApps: true)
    }

    private func requestMicrophonePermissionOnFirstLaunchIfNeeded() async {
        guard !settingsStore.settings.hasRequestedMicrophonePermissionOnFirstLaunch else {
            return
        }

        let granted = await session.requestPermissionIfNeeded(retryWhenDenied: false)
        settingsStore.update { settings in
            settings.hasRequestedMicrophonePermissionOnFirstLaunch = true
            settings.didGrantMicrophonePermissionOnFirstLaunch = granted
        }
    }

    private var transcribingModelText: String {
        switch settingsStore.settings.selectedEngine {
        case .whisperCpp:
            let modelPath = settingsStore.settings.whisperModelPath
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !modelPath.isEmpty else { return "whisper.cpp" }
            return URL(fileURLWithPath: modelPath).lastPathComponent
        case .openAI:
            let modelName = settingsStore.settings.apiModel
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !modelName.isEmpty else { return TranscriptionEngineKind.openAI.displayName }
            return modelName
        case .mlxOpenAIServer:
            let modelName = settingsStore.settings.mlxServedModelName
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !modelName.isEmpty else { return TranscriptionEngineKind.mlxOpenAIServer.displayName }
            return modelName
        }
    }

    private func formatDuration(_ seconds: Int) -> String {
        let minutes = seconds / 60
        let remainingSeconds = seconds % 60
        return String(format: "%02d:%02d", minutes, remainingSeconds)
    }
}

import AppKit
import Foundation
import os

// MARK: - Protocol

/// Abstraction over VADRecordingService for testability.
@MainActor
protocol VADRecordingServiceProtocol: AnyObject {
    func requestPermissionIfNeeded() async -> Bool
    @discardableResult
    func startRecording(
        config: SilenceDetectorConfig,
        onSegmentCompleted: @MainActor @Sendable @escaping (URL) -> Void,
        onError: @MainActor @Sendable @escaping (Error) -> Void
    ) throws -> URL
    func stopRecording() -> URL?
}

extension VADRecordingService: VADRecordingServiceProtocol {}

// MARK: - Coordinator

@MainActor
final class VADSessionCoordinator: ObservableObject {
    var onPhaseChange: ((AppController.Phase) -> Void)?
    var frontmostApp: NSRunningApplication?

    /// 会话结束后触发，携带统一结果与触发来源（热键/UI）。
    var onSessionCompleted: ((SessionResult, _ triggeredFromHotkey: Bool) -> Void)?
    /// 每完成一个 VAD 段落后触发，携带到目前为止的累积转录文本（用于增量写入剪贴板）。
    var onIncrementalTranscript: ((String) -> Void)?

    private(set) var lastTaskTranscript = ""

    private let transcriptionFlow: TranscriptionFlow
    private let settingsStore: SettingsStore
    private let recordingService: any VADRecordingServiceProtocol

    private var accumulatedTranscript = ""
    private var transcribedSegments: [String] = []
    private var accumulatedTranscriptionDuration: Double = 0
    private var segmentTranscriptionDurations: [Double] = []
    private var segmentTranscriptionApiDurations: [Double] = []
    private var pendingSegmentTasks: [Task<(String, Double?, Double?), any Error>] = []
    private var sessionStartedAt: Date?
    private var firstSegmentURL: URL?
    private var currentSessionID: UUID?
    private var isRecording = false
    private var isStartingSession = false
    private var sessionUnderstandingMode = false

    var onRecordingDurationUpdate: ((Int) -> Void)?
    private var recordingTimer: Timer?

    private static let logger = Logger(subsystem: "com.cocoscribe.app", category: "vad-session")

    init(
        transcriptionFlow: TranscriptionFlow,
        settingsStore: SettingsStore,
        recordingService: any VADRecordingServiceProtocol
    ) {
        self.transcriptionFlow = transcriptionFlow
        self.settingsStore = settingsStore
        self.recordingService = recordingService
    }

    func toggle(understandingMode: Bool, triggeredFromHotkey: Bool) async {
        if isRecording {
            await stopSession(triggeredFromHotkey: triggeredFromHotkey)
        } else if !isStartingSession {
            do {
                try await startSession(understandingMode: understandingMode, triggeredFromHotkey: triggeredFromHotkey)
            } catch {
                onPhaseChange?(.failed(TranscriptionFailure(reason: error.localizedDescription)))
            }
        }
        // Ignore hotkey presses while session is still initializing (isStartingSession == true)
    }

    func startSession(understandingMode: Bool, triggeredFromHotkey: Bool) async throws {
        // Guard against reentrant calls: set flag synchronously before any await so that
        // rapid hotkey presses during initialization are ignored by toggle().
        isStartingSession = true
        defer { isStartingSession = false }

        let sessionID = UUID()
        currentSessionID = sessionID

        pendingSegmentTasks.forEach { $0.cancel() }
        pendingSegmentTasks = []
        accumulatedTranscript = ""
        transcribedSegments = []
        accumulatedTranscriptionDuration = 0
        segmentTranscriptionDurations = []
        segmentTranscriptionApiDurations = []
        lastTaskTranscript = ""
        sessionUnderstandingMode = understandingMode

        let granted = await recordingService.requestPermissionIfNeeded()
        guard granted else {
            onPhaseChange?(.failed(TranscriptionFailure(reason: "Microphone access denied.")))
            return
        }

        let config = SilenceDetectorConfig(
            holdDuration: settingsStore.settings.silenceThresholdSeconds
        )

        firstSegmentURL = try recordingService.startRecording(
            config: config,
            onSegmentCompleted: { [weak self] url in
                self?.handleSegmentReady(url, sessionID: sessionID)
            },
            onError: { [weak self] error in
                self?.handleRecordingError(error)
            }
        )
        sessionStartedAt = Date()

        isRecording = true
        onPhaseChange?(.recording)
        startRecordingTimer()
        Self.logger.info("VAD session started, sessionID=\(sessionID)")
    }

    func stopSession(triggeredFromHotkey: Bool) async {
        guard isRecording else { return }
        isRecording = false
        stopRecordingTimer()
        onPhaseChange?(.transcribing)

        let postRecordingStart = Date()
        let lastURL = recordingService.stopRecording()

        _ = try? await pendingSegmentTasks.last?.value

        if let url = lastURL {
            await transcribeSegment(url)
        }

        // Understanding pass for continuousComprehend mode
        var finalTranscript = accumulatedTranscript
        var understandingTotalSec: Double? = nil
        var understandingApiSec: Double? = nil
        var suggestedTitle: String? = nil

        if sessionUnderstandingMode {
            onPhaseChange?(.refining)
            // 只有在菜单栏能感知到相位切换时，用户才会看到”理解中”。
            // 当 Ollama 处理非常快时，refining 可能会在极短时间内切到 completed，
            // 从而导致菜单栏胶囊来不及刷新显示。这里保证 refining 至少展示一段时间。
            let refiningStart = Date()
            do {
                let comprehendResult = try await transcriptionFlow.runTextProcessingOnly(
                    text: transcribedSegments.joined(separator: AppConstants.continuousComprehendSegmentSeparator),
                    settings: settingsStore.settings
                )
                finalTranscript = comprehendResult.refinedText
                understandingTotalSec = comprehendResult.totalDurationSeconds
                understandingApiSec = comprehendResult.apiDurationSeconds
                suggestedTitle = comprehendResult.suggestedTitle
            } catch {
                Self.logger.error("Understanding pass failed: \(error.localizedDescription)")
                onPhaseChange?(.failed(TranscriptionFailure(reason: error.localizedDescription)))
                return
            }

            let elapsed = Date().timeIntervalSince(refiningStart)
            if elapsed < AppConstants.minRefiningDisplaySeconds {
                let remainingSeconds = AppConstants.minRefiningDisplaySeconds - elapsed
                let remainingNanos = UInt64(remainingSeconds * 1_000_000_000)
                if remainingNanos > 0 {
                    try? await Task.sleep(nanoseconds: remainingNanos)
                }
            }
        }

        let settings = settingsStore.settings
        guard let audioURL = firstSegmentURL else {
            onPhaseChange?(.failed(TranscriptionFailure(reason: "No audio file recorded.")))
            return
        }

        let wallClock = sessionStartedAt.map { Date().timeIntervalSince($0) }
        let postRecordingSec = Date().timeIntervalSince(postRecordingStart)
        let metrics: [String: Double]? = {
            guard accumulatedTranscriptionDuration > 0 || understandingTotalSec != nil else { return nil }
            let totalApiMs = segmentTranscriptionApiDurations.reduce(0, +) * 1000
            var m: [String: Double] = [
                "pipeline.metrics.transcription.total_ms": accumulatedTranscriptionDuration * 1000,
                "pipeline.metrics.transcription.api_ms": totalApiMs
            ]
            for (i, dur) in segmentTranscriptionDurations.enumerated() {
                m["pipeline.metrics.transcription.seg\(i).total_ms"] = dur * 1000
                m["pipeline.metrics.transcription.seg\(i).api_ms"] = segmentTranscriptionApiDurations[i] * 1000
            }
            if let totalMs = understandingTotalSec.map({ $0 * 1000 }) {
                m["pipeline.metrics.textProcessing.total_ms"] = totalMs
            }
            if let apiMs = understandingApiSec.map({ $0 * 1000 }) {
                m["pipeline.metrics.textProcessing.api_ms"] = apiMs
            }
            return m
        }()
        let result = SessionResult(
            transcript: finalTranscript,
            rawTranscript: accumulatedTranscript,
            audioURL: audioURL,
            mode: sessionUnderstandingMode ? .continuousComprehend : .continuous,
            engine: settings.selectedEngine,
            recordingDurationSeconds: wallClock,
            transcriptionDurationSeconds: accumulatedTranscriptionDuration > 0 ? accumulatedTranscriptionDuration : nil,
            understandingDurationSeconds: understandingTotalSec,
            postRecordingDurationSeconds: postRecordingSec >= 0 ? postRecordingSec : nil,
            pipelineMetrics: metrics,
            suggestedTitle: suggestedTitle
        )
        lastTaskTranscript = finalTranscript
        Self.logger.info("VAD session stopped")

        onSessionCompleted?(result, triggeredFromHotkey)
        onPhaseChange?(.completed)
    }

    // MARK: - Private

    private func startRecordingTimer() {
        recordingTimer?.invalidate()
        let start = Date()
        recordingTimer = Timer.scheduledTimer(withTimeInterval: 1.0, repeats: true) { [weak self] _ in
            let elapsed = Int(Date().timeIntervalSince(start))
            Task { @MainActor [weak self] in
                self?.onRecordingDurationUpdate?(elapsed)
            }
        }
    }

    private func stopRecordingTimer() {
        recordingTimer?.invalidate()
        recordingTimer = nil
        onRecordingDurationUpdate?(0)
    }

    private func handleSegmentReady(_ url: URL, sessionID: UUID) {
        guard sessionID == currentSessionID else { return }

        let previousTask = pendingSegmentTasks.last
        let settings = settingsStore.settings
        let flow = transcriptionFlow

        let task = Task<(String, Double?, Double?), any Error> {
            _ = try? await previousTask?.value
            let result = try await flow.run(audioURL: url, settings: settings, understandingMode: false)
            return (result.transcript, result.transcriptionDurationSeconds, result.transcriptionApiDurationSeconds)
        }
        pendingSegmentTasks.append(task)

        Task { @MainActor [weak self] in
            guard let self, let (text, duration, apiDuration) = try? await task.value else { return }
            let trimmed = Self.trimSegment(text)
            self.transcribedSegments.append(trimmed)
            self.accumulatedTranscript += trimmed
            let dur = duration ?? 0
            self.accumulatedTranscriptionDuration += dur
            self.segmentTranscriptionDurations.append(dur)
            self.segmentTranscriptionApiDurations.append(apiDuration ?? dur)
            // 通知 AppController 最新的增量文本，由其决定是否写入剪贴板。
            if !self.sessionUnderstandingMode {
                self.onIncrementalTranscript?(self.accumulatedTranscript)
            }
        }
    }

    private func transcribeSegment(_ url: URL) async {
        let settings = settingsStore.settings
        do {
            let result = try await transcriptionFlow.run(audioURL: url, settings: settings, understandingMode: false)
            let trimmed = Self.trimSegment(result.transcript)
            transcribedSegments.append(trimmed)
            accumulatedTranscript += trimmed
            let dur = result.transcriptionDurationSeconds ?? 0
            accumulatedTranscriptionDuration += dur
            segmentTranscriptionDurations.append(dur)
            segmentTranscriptionApiDurations.append(result.transcriptionApiDurationSeconds ?? dur)
        } catch {
            Self.logger.error("Final segment transcription failed: \(error.localizedDescription)")
        }
    }

    /// Strip leading/trailing punctuation that Whisper adds at segment boundaries.
    private static func trimSegment(_ text: String) -> String {
        let punctuation: Set<Character> = ["﹑", "、", "，", "。", " ", "\n"]
        return String(text.drop(while: { punctuation.contains($0) })
                         .reversed()
                         .drop(while: { punctuation.contains($0) })
                         .reversed())
    }

    private func handleRecordingError(_ error: Error) {
        Self.logger.error("VAD recording error: \(error.localizedDescription)")
        Task { [weak self] in
            await self?.stopSession(triggeredFromHotkey: false)
        }
    }
}

