    @ViewBuilder
    private func menuButton(
        title: String,
        subtitle: String,
        symbol: String,
        id: String? = nil,
        shortcut: (key: KeyEquivalent, modifiers: SwiftUI.EventModifiers)?,
        action: @escaping () -> Void
    ) -> some View {
        // Use .plain so MenuItemRow's own hover state renders correctly.
        // keyboardShortcut on a .plain Button in a window-style MenuBarExtra
        // preserves the custom label (unlike native menu style).
        Group {
            if let shortcut {
                Button(action: action) {
                    MenuItemRow(title: title, subtitle: subtitle, symbol: symbol)
                }
                .buttonStyle(.plain)
                .keyboardShortcut(shortcut.key, modifiers: shortcut.modifiers)
            } else {
                Button(action: action) {
                    MenuItemRow(title: title, subtitle: subtitle, symbol: symbol)
                }
                .buttonStyle(.plain)
            }
        }
        .accessibilityIdentifier(id ?? title)
    }

    // ── Shortcut helpers ─────────────────────────────────────────

    private var recordingMenuShortcut: (key: KeyEquivalent, modifiers: SwiftUI.EventModifiers)? {
        menuShortcut(for: settingsStore.settings.hotkey)
    }
    private var historyMenuShortcut: (key: KeyEquivalent, modifiers: SwiftUI.EventModifiers)? {
        settingsStore.settings.openHistoryHotkey.flatMap { menuShortcut(for: $0) }
    }
    private var settingsMenuShortcut: (key: KeyEquivalent, modifiers: SwiftUI.EventModifiers)? {
        settingsStore.settings.openSettingsHotkey.flatMap { menuShortcut(for: $0) }
    }
    private var understandingModeMenuShortcut: (key: KeyEquivalent, modifiers: SwiftUI.EventModifiers)? {
        settingsStore.settings.understandingModeHotkey.flatMap { menuShortcut(for: $0) }
    }
    private var vadMenuShortcut: (key: KeyEquivalent, modifiers: SwiftUI.EventModifiers)? {
        settingsStore.settings.vadHotkey.flatMap { menuShortcut(for: $0) }
    }
    private var vadComprehendMenuShortcut: (key: KeyEquivalent, modifiers: SwiftUI.EventModifiers)? {
        settingsStore.settings.vadComprehendHotkey.flatMap { menuShortcut(for: $0) }
    }

    private func menuShortcut(for hotkey: HotkeyConfiguration) -> (key: KeyEquivalent, modifiers: SwiftUI.EventModifiers)? {
        guard let key = keyEquivalent(for: hotkey.keyCode) else { return nil }
        var mods: SwiftUI.EventModifiers = []
        if (hotkey.modifiers & UInt32(cmdKey))     != 0 { mods.insert(.command) }
        if (hotkey.modifiers & UInt32(shiftKey))   != 0 { mods.insert(.shift) }
        if (hotkey.modifiers & UInt32(optionKey))  != 0 { mods.insert(.option) }
        if (hotkey.modifiers & UInt32(controlKey)) != 0 { mods.insert(.control) }
        return (key, mods)
    }

    private func keyEquivalent(for keyCode: UInt32) -> KeyEquivalent? {
        let map: [UInt32: KeyEquivalent] = [
            0:"a",1:"s",2:"d",3:"f",4:"h",5:"g",6:"z",7:"x",8:"c",9:"v",11:"b",
            12:"q",13:"w",14:"e",15:"r",16:"y",17:"t",18:"1",19:"2",20:"3",21:"4",
            22:"6",23:"5",24:"=",25:"9",26:"7",27:"-",28:"8",29:"0",30:"]",31:"o",
            32:"u",33:"[",34:"i",35:"p",37:"l",38:"j",39:"'",40:"k",41:";",42:"\\",
            43:",",44:"/",45:"n",46:"m",47:".",49:.space,50:"`",53:.escape,
            123:.leftArrow,124:.rightArrow,125:.downArrow,126:.upArrow
        ]
        return map[keyCode]
    }
}

