private struct WaveformBars: View {
    let accent: Color
    let level: Float

    private let barCount = 22
    // Per-bar multipliers (0.6…1.4) derived from the old duration array,
    // normalized so each bar shows organic variation around the shared level.
    private let multipliers: [Float] = [
        0.72, 0.88, 0.64, 1.05, 0.78, 0.59, 0.95, 0.82, 0.70, 1.10,
        0.76, 0.91, 0.65, 0.85, 0.73, 1.00, 0.68, 0.94, 0.80, 0.60,
        0.77, 0.89
    ]

    var body: some View {
        HStack(alignment: .center, spacing: 3) {
            ForEach(0..<barCount, id: \.self) { i in
                WaveBar(
                    accent: accent,
                    level: level,
                    multiplier: multipliers[i % multipliers.count]
                )
            }
        }
    }
}

private struct WaveBar: View {
    let accent: Color
    let level: Float
    let multiplier: Float

    private var barHeight: CGFloat {
        // minimum 4pt, maximum 32pt — scale linearly with level × multiplier
        let scaled = CGFloat(level * multiplier)
        return max(4, min(32, 4 + scaled * 28))
    }

    var body: some View {
        RoundedRectangle(cornerRadius: 2, style: .continuous)
            .fill(accent.opacity(level > 0.02 ? 0.85 : 0.25))
            .frame(width: 3, height: barHeight)
            .animation(.easeOut(duration: 0.08), value: barHeight)
    }
}

