import AVFoundation
import Foundation
import os

/// Wraps SegmentedAudioWriter + SilenceDetector.
/// The tap block runs on the audio I/O thread; SilenceDetector mutation is
/// confined to that thread via a DetectorBox captured in the vadCallback.
@MainActor
final class VADRecordingService {
    private let writer = SegmentedAudioWriter()
    private static let logger = Logger(subsystem: "com.cocoscribe.app", category: "vad-recording")

    func requestPermissionIfNeeded() async -> Bool {
        switch AVCaptureDevice.authorizationStatus(for: .audio) {
        case .authorized: return true
        case .denied, .restricted: return false
        case .notDetermined:
            return await withCheckedContinuation { cont in
                AVCaptureDevice.requestAccess(for: .audio) { cont.resume(returning: $0) }
            }
        @unknown default: return false
        }
    }

    /// Start VAD recording. Returns the URL of the first segment file.
    /// `onSegmentCompleted` and `onError` are called on the main actor.
    func startRecording(
        config: SilenceDetectorConfig,
        onSegmentCompleted: @MainActor @Sendable @escaping (URL) -> Void,
        onError: @MainActor @Sendable @escaping (Error) -> Void
    ) throws -> URL {
        let recordingsDirectory = try recordingsDir()
        let sessionTag = ISO8601DateFormatter().string(from: Date())
            .replacingOccurrences(of: ":", with: "-")

        // Box wraps SilenceDetector so the @Sendable vadCallback can mutate it
        // on the audio I/O thread. All access is single-threaded (tap block).
        let box = DetectorBox(SilenceDetector(config: config))

        writer.onSegmentCompleted = { url in
            onSegmentCompleted(url)
        }
        writer.onError = { error in
            onError(error)
        }

        // vadCallback runs on audio I/O thread; returns true to request a roll.
        // bufferDur = duration of the current buffer (not running segment total).
        // resetSegment() called before roll completes so new segment tracking starts clean.
        writer.vadCallback = { rms, bufferDur in
            let shouldCut = box.detector.process(rms: rms, bufferDuration: bufferDur)
            if shouldCut { box.detector.resetSegment() }
            return shouldCut
        }

        return try writer.start(recordingsDirectory: recordingsDirectory, sessionTag: sessionTag)
    }

    func stopRecording() -> URL? {
        writer.stop()
    }

    private func recordingsDir() throws -> URL {
        let fm = FileManager.default
        let dir = fm.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent(AppConstants.appSupportDirectoryName)
            .appendingPathComponent(AppConstants.recordingsSubdirectoryName)
        try fm.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }
}

// MARK: - DetectorBox

/// Reference-type wrapper for SilenceDetector so a @Sendable closure can mutate it.
/// All access must be from the same thread (audio I/O thread via vadCallback).
private final class DetectorBox {
    var detector: SilenceDetector
    init(_ d: SilenceDetector) { detector = d }
}

import Foundation

/// 单次转录流程的返回结果：最终文本、AI 生成标题及可选的转录/理解耗时（秒）。
struct TranscriptionFlowResult {
    let transcript: String
    let suggestedTitle: String?
    let rawTranscript: String?
    let transcriptionDurationSeconds: Double?
    let transcriptionApiDurationSeconds: Double?
    let understandingDurationSeconds: Double?
}

/// 编排「转录 + 可选文本处理（如 Ollama 润色）」流程；仅负责产出文本，不写 TaskStore 或剪贴板。
struct TranscriptionFlow {
    private let transcriptionService: TranscriptionServiceProtocol
    private let textProcessors: [TextProcessingServiceProtocol]

    init(
        transcriptionService: TranscriptionServiceProtocol,
        textProcessors: [TextProcessingServiceProtocol] = []
    ) {
        self.transcriptionService = transcriptionService
        self.textProcessors = textProcessors
    }

    /// 对给定音频执行转录；若 `understandingMode` 为 true 则再走 Ollama 润色。返回结果（文本 + 可选转录/理解耗时）或抛出错误。
    func run(
        audioURL: URL,
        settings: AppSettings,
        understandingMode: Bool,
        transcriptionContext: StageContext? = nil,
        textProcessingContext: StageContext? = nil
    ) async throws -> TranscriptionFlowResult {
        let t0 = Date()
        let transcribedText: String
        var transcriptionApiDuration: Double?
        if let context = transcriptionContext {
            transcribedText = try await context.measureApi {
                try await transcriptionService.transcribe(
                    audioURL: audioURL,
                    settings: settings,
                    engine: settings.selectedEngine
                )
            }
        } else {
            let apiStart = Date()
            transcribedText = try await transcriptionService.transcribe(
                audioURL: audioURL,
                settings: settings,
                engine: settings.selectedEngine
            )
            let apiDur = Date().timeIntervalSince(apiStart)
            transcriptionApiDuration = apiDur >= 0 ? apiDur : nil
        }
        let transDuration = Date().timeIntervalSince(t0)

        if
            let context = transcriptionContext,
            let config = context.metricsConfig,
            config.recordTotalDuration,
            let collector = context.metricsCollector
        {
            let durationMs = transDuration * 1000
            if durationMs >= 0 {
                collector.recordStageTotal(for: context.metricsKey, durationMs: durationMs)
            }
        }

        var transcript = transcribedText
        var suggestedTitle: String?

        var understandingDurationSeconds: Double?
        if understandingMode, !textProcessors.isEmpty {
            let r0 = Date()
            for processor in textProcessors {
                let output: RefinedOutput
                if let context = textProcessingContext {
                    output = try await context.measureApi {
                        try await processor.process(text: transcript, settings: settings)
                    }
                } else {
                    output = try await processor.process(text: transcript, settings: settings)
                }
                transcript = output.text
                suggestedTitle = output.suggestedTitle
            }
            let refineDuration = Date().timeIntervalSince(r0)
            understandingDurationSeconds = refineDuration >= 0 ? refineDuration : nil

            if
                let context = textProcessingContext,
                let config = context.metricsConfig,
                config.recordTotalDuration,
                let collector = context.metricsCollector
            {
                let durationMs = refineDuration * 1000
                if durationMs >= 0 {
                    collector.recordStageTotal(for: context.metricsKey, durationMs: durationMs)
                }
            }
        }

        return TranscriptionFlowResult(
            transcript: transcript,
            suggestedTitle: suggestedTitle,
            rawTranscript: transcribedText,
            transcriptionDurationSeconds: transDuration >= 0 ? transDuration : nil,
            transcriptionApiDurationSeconds: transcriptionApiDuration,
            understandingDurationSeconds: understandingDurationSeconds
        )
    }

    /// Runs only the text-processing stage (e.g. Ollama) on pre-transcribed text.
    /// Does not call the transcription service. Used by VAD continuous-comprehend mode.
    func runTextProcessingOnly(
        text: String,
        settings: AppSettings
    ) async throws -> (refinedText: String, suggestedTitle: String?, totalDurationSeconds: Double, apiDurationSeconds: Double) {
        let t0 = Date()
        var result = text
        var suggestedTitle: String?
        let apiStart = Date()
        for processor in textProcessors {
            let output = try await processor.process(text: result, settings: settings)
            result = output.text
            suggestedTitle = output.suggestedTitle
        }
        let apiDuration = Date().timeIntervalSince(apiStart)
        let totalDuration = Date().timeIntervalSince(t0)
        return (
            refinedText: result,
            suggestedTitle: suggestedTitle,
            totalDurationSeconds: totalDuration >= 0 ? totalDuration : 0,
            apiDurationSeconds: apiDuration >= 0 ? apiDuration : 0
        )
    }
}

import Foundation

struct SilenceDetectorConfig {
    var thresholdDBFS: Float = -55.0
    var holdDuration: TimeInterval = 3.0
    var minSegmentDuration: TimeInterval = 0.5
}

/// Pure value-type VAD state machine. Feed each PCM buffer's RMS and duration;
/// call `resetSegment()` after each cut.
struct SilenceDetector {
    let config: SilenceDetectorConfig

    private var silenceDuration: TimeInterval = 0
    /// Accumulates only non-silent (speech) audio duration within the current segment.
    private var speechDuration: TimeInterval = 0

    init(config: SilenceDetectorConfig) {
        self.config = config
    }

    /// Returns `true` when the detector wants to cut a new segment.
    /// Caller must call `resetSegment()` after acting on a `true` return.
    mutating func process(rms: Float, bufferDuration: TimeInterval) -> Bool {
        let dBFS = rms > 0 ? 20 * log10(rms) : -Float.infinity
        if dBFS < config.thresholdDBFS {
            silenceDuration += bufferDuration
        } else {
            silenceDuration = 0
            speechDuration += bufferDuration
        }

        guard silenceDuration >= config.holdDuration else { return false }

        if speechDuration < config.minSegmentDuration {
            // Segment too short — skip cut, reset timers
            silenceDuration = 0
            speechDuration = 0
            return false
        }

        return true
    }

    /// Reset silence and segment tracking for a new segment.
    mutating func resetSegment() {
        silenceDuration = 0
        speechDuration = 0
    }
}

import AVFoundation
import Foundation
import os

/// Manages an AVAudioEngine input tap and a swappable AVAudioFile.
/// File I/O runs on a dedicated serial queue to avoid blocking the real-time audio thread.
/// Thread-safe: all public methods may be called from any thread.
final class SegmentedAudioWriter {
    private let engine = AVAudioEngine()
    private let writerQueue = DispatchQueue(label: "com.cocoscribe.vad.writer-io")
    private static let logger = Logger(subsystem: "com.cocoscribe.app", category: "vad-writer")

    private var currentFile: AVAudioFile?
    private var currentFileURL: URL?
    private var segmentIndex: Int = 0
    private var framesWrittenInCurrentSegment: UInt32 = 0
    private var sampleRate: Double = 16_000

    // Ring buffer for frames arriving during a file swap (≤ 64 frames worth of buffers)
    private var pendingBuffers: [AVAudioPCMBuffer] = []
    private var isSwapping = false

    var onSegmentCompleted: (@MainActor @Sendable (URL) -> Void)?
    var onError: (@MainActor @Sendable (Error) -> Void)?

    /// Called on the audio I/O thread after each buffer write.
    /// Receives (rms, bufferDurationSeconds). Return true to request a roll.
    var vadCallback: ((Float, TimeInterval) -> Bool)?

    // Stored at start() time so rollToNextSegment can access them from handleBuffer
    private var storedRecordingsDirectory: URL?
    private var storedSessionTag: String?

    enum WriterError: LocalizedError {
        case engineStartFailed
        case fileCreationFailed(URL, Error)

        var errorDescription: String? {
            switch self {
            case .engineStartFailed: return "AVAudioEngine failed to start."
            case .fileCreationFailed(let url, let err): return "Cannot create audio file at \(url.lastPathComponent): \(err.localizedDescription)"
            }
        }
    }

    /// Start recording. Returns the URL of the first segment file.
    func start(recordingsDirectory: URL, sessionTag: String) throws -> URL {
        let inputNode = engine.inputNode
        let format = inputNode.outputFormat(forBus: 0)
        sampleRate = format.sampleRate

        segmentIndex = 0
        framesWrittenInCurrentSegment = 0
        pendingBuffers = []
        isSwapping = false

        storedRecordingsDirectory = recordingsDirectory
        storedSessionTag = sessionTag

        let firstURL = segmentURL(in: recordingsDirectory, tag: sessionTag, index: 0)
        currentFile = try makeAudioFile(at: firstURL, format: format)
        currentFileURL = firstURL

        inputNode.installTap(onBus: 0, bufferSize: 1024, format: format) { [weak self] buffer, _ in
            self?.handleBuffer(buffer)
        }

        try engine.start()
        return firstURL
    }

    /// Stop recording. Returns the URL of the last segment file.
    func stop() -> URL? {
        engine.inputNode.removeTap(onBus: 0)
        engine.stop()
        var url: URL?
        writerQueue.sync {
            url = currentFileURL
            currentFile = nil
            currentFileURL = nil
        }
        return url
    }

    /// Approximate current segment duration. Updated on audio I/O thread only.
    /// Only valid when called from the audio I/O thread (e.g., inside the tap block).
    var currentSegmentDuration: TimeInterval {
        TimeInterval(framesWrittenInCurrentSegment) / max(sampleRate, 1)
    }

    /// Roll to a new segment file. Called from the tap block (audio I/O thread).
    func rollToNextSegment(recordingsDirectory: URL, sessionTag: String) {
        guard !isSwapping else { return }
        isSwapping = true

        let closedURL = currentFileURL
        let nextIndex = segmentIndex + 1
        let nextURL = segmentURL(in: recordingsDirectory, tag: sessionTag, index: nextIndex)
        let format = engine.inputNode.outputFormat(forBus: 0)

        writerQueue.async { [weak self] in
            guard let self else { return }
            self.currentFile = nil  // closes current file

            do {
                let newFile = try self.makeAudioFile(at: nextURL, format: format)
                // Flush pending buffers
                for buf in self.pendingBuffers {
                    try? newFile.write(from: buf)
                }
                self.pendingBuffers.removeAll()
                self.currentFile = newFile
                self.currentFileURL = nextURL
                self.segmentIndex = nextIndex
                self.framesWrittenInCurrentSegment = 0
                self.isSwapping = false

                if let closed = closedURL {
                    let completionHandler = self.onSegmentCompleted
                    Task { @MainActor in
                        completionHandler?(closed)
                    }
                }
            } catch {
                self.isSwapping = false
                Self.logger.error("Failed to open next segment file: \(error.localizedDescription)")
                let errorHandler = self.onError
                let writerError = WriterError.fileCreationFailed(nextURL, error)
                Task { @MainActor in
                    errorHandler?(writerError)
                }
            }
        }
    }

    // MARK: - Private

    private func handleBuffer(_ buffer: AVAudioPCMBuffer) {
        framesWrittenInCurrentSegment += buffer.frameLength

        // VAD: compute per-buffer RMS and duration, invoke callback, roll if needed
        let bufDur = TimeInterval(buffer.frameLength) / max(sampleRate, 1)
        if !isSwapping,
           let dir = storedRecordingsDirectory,
           let tag = storedSessionTag,
           vadCallback?(rmsOf(buffer), bufDur) == true {
            rollToNextSegment(recordingsDirectory: dir, sessionTag: tag)
        }

        if isSwapping {
            if pendingBuffers.count < 64 {
                pendingBuffers.append(buffer)
            } else {
                Self.logger.warning("Ring buffer full — dropping audio buffer during segment swap")
            }
            return
        }
        writerQueue.async { [weak self] in
            guard let self, let file = self.currentFile else { return }
            do { try file.write(from: buffer) } catch {
                Self.logger.error("Audio write error: \(error.localizedDescription)")
            }
        }
    }

    private func rmsOf(_ buffer: AVAudioPCMBuffer) -> Float {
        guard let data = buffer.floatChannelData?[0], buffer.frameLength > 0 else { return 0 }
        let frames = UnsafeBufferPointer(start: data, count: Int(buffer.frameLength))
        let sumSq = frames.reduce(Float(0)) { $0 + $1 * $1 }
        return sqrt(sumSq / Float(buffer.frameLength))
    }

    private func makeAudioFile(at url: URL, format: AVAudioFormat) throws -> AVAudioFile {
        try AVAudioFile(forWriting: url, settings: format.settings)
    }

    private func segmentURL(in directory: URL, tag: String, index: Int) -> URL {
        directory.appendingPathComponent("recording-\(tag)-seg\(String(format: "%03d", index)).wav")
    }
}

