import XCTest
import AVFoundation
@testable import MacSTTTool

final class WAVFileSegmenterTests: XCTestCase {

    func testSegmentsOnSpeechSilenceSpeech() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }

        let sampleRate: Double = 16_000
        let format = AVAudioFormat(standardFormatWithSampleRate: sampleRate, channels: 1)!

        let sourceURL = dir.appendingPathComponent("source.wav")
        // Wrapped in a do-block so the AVAudioFile writer is flushed and closed
        // (deinit) before we attempt to read it in segmenter.segment().
        do {
            let sourceFile = try AVAudioFile(forWriting: sourceURL, settings: format.settings)

            // 0.6s speech (amplitude 0.5 → dBFS ≈ -6, well above -55 threshold)
            let speech1 = makePCMBuffer(format: format, frames: 9_600, amplitude: 0.5)
            try sourceFile.write(from: speech1)

            // 3.5s silence (zeros → dBFS = -inf, below threshold)
            let silence = makePCMBuffer(format: format, frames: 56_000, amplitude: 0.0)
            try sourceFile.write(from: silence)

            // 0.8s speech
            let speech2 = makePCMBuffer(format: format, frames: 12_800, amplitude: 0.5)
            try sourceFile.write(from: speech2)
        }

        let outDir = dir.appendingPathComponent("segments")
        try FileManager.default.createDirectory(at: outDir, withIntermediateDirectories: true)

        let config = SilenceDetectorConfig(
            thresholdDBFS: -55.0,
            holdDuration: 3.0,
            minSegmentDuration: 0.5
        )
        let segmenter = WAVFileSegmenter(config: config)
        let segments = try segmenter.segment(sourceURL: sourceURL, outputDirectory: outDir, sessionTag: "test")

        XCTAssertEqual(segments.count, 2, "Expected 2 segments; got \(segments.count)")

        for url in segments {
            XCTAssertTrue(FileManager.default.fileExists(atPath: url.path), "Segment file missing: \(url.lastPathComponent)")
            let attrs = try FileManager.default.attributesOfItem(atPath: url.path)
            let size = attrs[.size] as? Int ?? 0
            XCTAssertGreaterThan(size, 44, "Segment file \(url.lastPathComponent) is empty (only WAV header)")
        }
    }

    func testSingleSegmentWhenNoSilence() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }

        let format = AVAudioFormat(standardFormatWithSampleRate: 16_000, channels: 1)!
        let sourceURL = dir.appendingPathComponent("source.wav")
        // Wrapped in a do-block so the writer is flushed/closed before reading.
        do {
            let sourceFile = try AVAudioFile(forWriting: sourceURL, settings: format.settings)

            // 2s of continuous speech, no silence
            let speech = makePCMBuffer(format: format, frames: 32_000, amplitude: 0.5)
            try sourceFile.write(from: speech)
        }

        let outDir = dir.appendingPathComponent("segments")
        try FileManager.default.createDirectory(at: outDir, withIntermediateDirectories: true)

        let config = SilenceDetectorConfig(holdDuration: 3.0, minSegmentDuration: 0.5)
        let segmenter = WAVFileSegmenter(config: config)
        let segments = try segmenter.segment(sourceURL: sourceURL, outputDirectory: outDir, sessionTag: "nosil")

        XCTAssertEqual(segments.count, 1)
    }

    // MARK: - Helpers

    private func makePCMBuffer(format: AVAudioFormat, frames: AVAudioFrameCount, amplitude: Float) -> AVAudioPCMBuffer {
        let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: frames)!
        buffer.frameLength = frames
        if let data = buffer.floatChannelData?[0] {
            for i in 0..<Int(frames) { data[i] = amplitude }
        }
        return buffer
    }
}
