// Sources/MacSTTTool/Experiment/WAVFileSegmenter.swift
import AVFoundation
import Foundation

/// Reads a WAV file offline and applies the same VAD logic as live recording.
///
/// Feeds PCM data in 1024-frame chunks (matching SegmentedAudioWriter's tap buffer size).
/// bufferDuration = frameLength / sampleRate replicates the per-buffer duration the real-time
/// tap delivers to SilenceDetector. Cut points are therefore identical to live recording.
///
/// When the detector fires, the triggering buffer starts the next segment (matching
/// SegmentedAudioWriter behavior where the cutting buffer goes into pendingBuffers → new file).
struct WAVFileSegmenter {
    /// Must match SegmentedAudioWriter's installTap bufferSize to produce identical cut points.
    static let tapBufferFrameCount: AVAudioFrameCount = 1024

    let config: SilenceDetectorConfig

    enum SegmenterError: LocalizedError {
        case cannotReadFile(URL)
        case cannotWriteSegment(URL, Error)

        var errorDescription: String? {
            switch self {
            case .cannotReadFile(let url): return "Cannot open WAV file: \(url.lastPathComponent)"
            case .cannotWriteSegment(let url, let err): return "Cannot write segment \(url.lastPathComponent): \(err.localizedDescription)"
            }
        }
    }

    /// Segments `sourceURL` using the same VAD logic as live recording.
    /// Writes segment WAV files into `outputDirectory` named `exp-<sessionTag>-seg000.wav`, etc.
    /// Returns URLs of all segment files in order. Empty-audio segments (file size ≤ 44 bytes) are filtered out.
    func segment(sourceURL: URL, outputDirectory: URL, sessionTag: String) throws -> [URL] {
        guard let sourceFile = try? AVAudioFile(forReading: sourceURL) else {
            throw SegmenterError.cannotReadFile(sourceURL)
        }

        let format = sourceFile.processingFormat
        let sampleRate = format.sampleRate
        var detector = SilenceDetector(config: config)
        var segmentURLs: [URL] = []
        var segmentIndex = 0

        func nextURL() -> URL {
            outputDirectory.appendingPathComponent(
                "exp-\(sessionTag)-seg\(String(format: "%03d", segmentIndex)).wav"
            )
        }

        var currentURL = nextURL()
        segmentURLs.append(currentURL)
        var currentFile: AVAudioFile? = try {
            do { return try AVAudioFile(forWriting: currentURL, settings: format.settings) }
            catch { throw SegmenterError.cannotWriteSegment(currentURL, error) }
        }()

        let readBuffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: Self.tapBufferFrameCount)!

        while sourceFile.framePosition < sourceFile.length {
            try sourceFile.read(into: readBuffer, frameCount: Self.tapBufferFrameCount)
            guard readBuffer.frameLength > 0 else { break }

            let rms = rmsOf(readBuffer)
            let bufferDuration = Double(readBuffer.frameLength) / sampleRate
            let shouldCut = detector.process(rms: rms, bufferDuration: bufferDuration)

            if shouldCut {
                detector.resetSegment()
                // Close current segment WITHOUT the triggering buffer (matching SegmentedAudioWriter
                // pendingBuffers behavior: the cutting buffer goes to the next segment).
                currentFile = nil
                segmentIndex += 1
                currentURL = nextURL()
                segmentURLs.append(currentURL)
                do {
                    currentFile = try AVAudioFile(forWriting: currentURL, settings: format.settings)
                } catch {
                    throw SegmenterError.cannotWriteSegment(currentURL, error)
                }
            }

            // Write buffer to current segment (first buffer of new segment when just cut)
            do {
                try currentFile?.write(from: readBuffer)
            } catch {
                throw SegmenterError.cannotWriteSegment(currentURL, error)
            }
        }

        // Close last segment
        currentFile = nil

        // Filter out empty segments (file size ≤ 44 bytes = WAV header only)
        return segmentURLs.filter { url in
            let size = (try? FileManager.default.attributesOfItem(atPath: url.path)[.size] as? Int) ?? 0
            return size > 44
        }
    }

    private func rmsOf(_ buffer: AVAudioPCMBuffer) -> Float {
        guard let data = buffer.floatChannelData?[0], buffer.frameLength > 0 else { return 0 }
        let frames = UnsafeBufferPointer(start: data, count: Int(buffer.frameLength))
        let sumSq = frames.reduce(Float(0)) { $0 + $1 * $1 }
        return sqrt(sumSq / Float(buffer.frameLength))
    }
}

